/**
 * @distilled.cloud/polymarket -- Polymarket SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from Polymarket's REST OpenAPI
 * documents, mirrored at `specs/spec-mirror-polymarket/specs/`. Everything
 * else in this folder is hand-written.
 *
 * One module per API, each on its own host: `gamma` (markets, events),
 * `clob` (order book, orders), `data` (positions, activity), `relayer`,
 * `bridge`, `combosRfq` and `perps`. Public reads need no credentials; CLOB
 * L2 requests are signed when `CLOB_API_KEY`, `CLOB_SECRET`,
 * `CLOB_PASS_PHRASE` and `POLY_ADDRESS` are set. L1 (EIP-712 wallet)
 * signing and the WebSocket APIs are not covered.
 *
 * @example
 * ```ts
 * import * as Polymarket from "@distilled.cloud/polymarket";
 *
 * const markets = yield* Polymarket.gamma.listMarkets({ limit: 5, closed: false });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  BridgeProtocol,
  ClobProtocol,
  CombosRfqProtocol,
  DataProtocol,
  GammaProtocol,
  PerpsProtocol,
  RelayerProtocol,
  type PolymarketOpError,
  type PolymarketOpContext,
} from "./protocol.ts";
export { signL2 } from "./signing.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
